import 'package:cloud_firestore/cloud_firestore.dart';
class Meeting { final String id,agenda,decisions; final DateTime date; final List<String> attendance; const Meeting({required this.id,required this.date,this.agenda='',this.decisions='',this.attendance=const[]}); factory Meeting.fromMap(String id, Map<String,dynamic> m)=>Meeting(id:id,date:(m['date'] as Timestamp?)?.toDate()??DateTime.now(),agenda:m['agenda']??'',decisions:m['decisions']??'',attendance:List<String>.from(m['attendance']??[])); Map<String,dynamic> toMap()=>{'date':Timestamp.fromDate(date),'agenda':agenda,'decisions':decisions,'attendance':attendance}; @override String toString()=> '$agenda • ${attendance.length} attended'; }
